INSERT INTO chapters(module_id,title,title_translation,description,description_translation,planned_lesson_count,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES(v_module,'Telefonnummer und erste Zahlen','شماره تلفن و اولین عددها','Raha lernt mit Lena, eine kurze Telefonnummer zu verstehen und zu nennen, und nutzt Name, Herkunft, Wohnort und Nummer später selbstständig bei einer Kursanmeldung.','رها با لنا یاد می‌گیرد یک شماره تلفن کوتاه را بفهمد و بگوید و بعد نام، مبدأ، محل زندگی و شماره را مستقل در ثبت‌نام کلاس به کار می‌برد.',4,1,1,4,'validated',JSON_OBJECT('series',4,'contractVersion','3.0.0','foundationRevision','3.2.0','qualityRevision','3.2.1'));
