(v_course,'chunk','de:a1:telefonnummer-fragen','Wie ist deine Telefonnummer?','شماره تلفنت چنده؟','پرسیدن شماره تلفن در گفتگوی غیررسمی ساده','A1',1,JSON_OBJECT('series',4),JSON_OBJECT('series',4)),
(v_course,'construction','de:a1:meine-telefonnummer-ist','Meine Telefonnummer ist + Ziffern','شماره تلفن من ... است','گفتن شماره تلفن به صورت دنباله رقم‌ها','A1',1,JSON_OBJECT('series',4),JSON_OBJECT('series',4)),
(v_course,'construction','de:a1:ziffern-0-5','null, eins, zwei, drei, vier, fünf','عددهای صفر تا پنج','تشخیص و تولید رقم‌های پایه در توالی کوتاه','A1',1,JSON_OBJECT('series',4),JSON_OBJECT('series',4)),
(v_course,'grammar','de:a1:possessive-meine-telefonnummer','meine Telefonnummer','شماره تلفن من','کاربرد پایه meine با اسم مونث Telefonnummer به صورت chunk-supported','A1',1,JSON_OBJECT('series',4),JSON_OBJECT('series',4)),
(v_course,'pronunciation','de:a1:pron:z-ts-zwei','z = /ts/ in zwei','صدای z در zwei','برای فارسی‌زبان: z آلمانی در zwei مثل ز فارسی نیست؛ با بسته‌شدن t و سپس s تولید می‌شود.','A1',1,JSON_OBJECT('series',4),JSON_OBJECT('series',4)),
(v_course,'can_do','de:a1:can:phone-number','Telefonnummer verstehen und nennen','فهمیدن و گفتن شماره تلفن','یک شماره کوتاه را بشنود، بخواند و در ثبت‌نام ساده بگوید','A1',1,JSON_OBJECT('series',4),JSON_OBJECT('series',4))
