INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES
(v_chapter,v_c_lena,v_c_raha,'Deine Telefonnummer','شماره تلفنت','Lena speichert Rahas Nummer und führt die ersten Ziffern in einem echten Kontaktmoment ein.','لنا شماره رها را ذخیره می‌کند و اولین رقم‌ها در یک موقعیت واقعی تماس معرفی می‌شوند.','story','berlin_new_start',13,1,430,1,'validated',JSON_OBJECT('pedagogicalRole','exposure')),
(v_chapter,v_c_lena,v_c_raha,'Null bis fünf','صفر تا پنج','Raha unterscheidet die Ziffern null bis fünf und übt die Frage nach einer Telefonnummer.','رها رقم‌های صفر تا پنج را تشخیص می‌دهد و پرسیدن شماره تلفن را تمرین می‌کند.','story','berlin_new_start',14,1,440,2,'validated',JSON_OBJECT('pedagogicalRole','explicit_form')),
(v_chapter,v_c_lena,v_c_raha,'Kontaktangaben verbinden','ترکیب اطلاعات تماس','Raha ruft Herkunft, Wohnort und Telefonnummer ab und verbindet bekannte Angaben mit der neuen Nummer.','رها مبدأ، محل زندگی و شماره تلفن را بازیابی می‌کند و اطلاعات قبلی را با شماره تازه ترکیب می‌کند.','story','berlin_new_start',15,1,440,3,'validated',JSON_OBJECT('pedagogicalRole','retrieval')),
(v_chapter,v_c_jonas,v_c_raha,'Bei der Kursanmeldung','در ثبت‌نام کلاس','Bei Jonas in der Sprachschule gibt Raha ohne Lena ihre wichtigsten Angaben und eine kurze Telefonnummer an.','رها نزد یوناس در آموزشگاه، بدون کمک لنا اطلاعات اصلی و یک شماره کوتاه را مستقل می‌گوید.','story','berlin_new_start',16,1,500,4,'validated',JSON_OBJECT('pedagogicalRole','mastery'));
INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,metadata) VALUES
(v_l_1,v_c_lena,1,'character','Raha, ich speichere deine Nummer. Wie ist deine Telefonnummer?','رها، شماره‌ات را ذخیره می‌کنم. شماره تلفنت چنده؟',1,'nova/audio/turns/de-fa/A1/s0004/l01/t01.mp3',NULL,NULL,NULL,JSON_ARRAY('Raha','ich','speichere','deine','Nummer','Wie','ist','deine','Telefonnummer'),JSON_OBJECT('series',4)),
(v_l_1,v_c_raha,2,'learner','Meine Telefonnummer ist null eins zwei drei.','شماره تلفن من صفر یک دو سه است.',1,'nova/audio/turns/de-fa/A1/s0004/l01/t02.mp3',NULL,'Meine Telefonnummer ist null eins zwei drei.',JSON_ARRAY('Meine Telefonnummer ist null eins zwei drei.','Null eins zwei drei.'),JSON_ARRAY('Meine','Telefonnummer','ist','null','eins','zwei','drei'),JSON_OBJECT('series',4)),
(v_l_1,v_c_lena,3,'character','Null eins zwei drei. Richtig?','صفر یک دو سه. درسته؟',1,'nova/audio/turns/de-fa/A1/s0004/l01/t03.mp3',NULL,NULL,NULL,JSON_ARRAY('Null','eins','zwei','drei','Richtig'),JSON_OBJECT('series',4)),
(v_l_1,v_c_raha,4,'learner','Ja, richtig.','بله، درسته.',1,'nova/audio/turns/de-fa/A1/s0004/l01/t04.mp3',NULL,'Ja, richtig.',JSON_ARRAY('Ja, richtig.','Ja, genau.'),JSON_ARRAY('Ja','richtig'),JSON_OBJECT('series',4)),
(v_l_1,v_c_lena,5,'character','Gut. Dann kann ich dir schreiben.','خوبه. پس می‌توانم بهت پیام بدهم.',1,'nova/audio/turns/de-fa/A1/s0004/l01/t05.mp3',NULL,NULL,NULL,JSON_ARRAY('Gut','Dann','kann','ich','dir','schreiben'),JSON_OBJECT('series',4)),
(v_l_1,v_c_raha,6,'learner','Super, danke.','عالیه، ممنون.',1,'nova/audio/turns/de-fa/A1/s0004/l01/t06.mp3',NULL,'Super, danke.',JSON_ARRAY('Super, danke.','Danke, super.'),JSON_ARRAY('Super','danke'),JSON_OBJECT('series',4)),
(v_l_1,v_c_lena,7,'character','Und meine Nummer kommt danach.','و بعدش شماره من را می‌دهم.',1,'nova/audio/turns/de-fa/A1/s0004/l01/t07.mp3',NULL,NULL,NULL,JSON_ARRAY('Und','meine','Nummer','kommt','danach'),JSON_OBJECT('series',4)),
(v_l_1,v_c_raha,8,'learner','Okay, gern.','باشه، با کمال میل.',1,'nova/audio/turns/de-fa/A1/s0004/l01/t08.mp3',NULL,'Okay, gern.',JSON_ARRAY('Okay, gern.','Ja, gern.'),JSON_ARRAY('Okay','gern'),JSON_OBJECT('series',4));
