INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_1,'listen',1,'Wie ist deine Telefonnummer?','اول گوش کن و هدف سوال را بفهم.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'new_word',2,'Meine Telefonnummer ist ...','الگوی گفتن شماره را به صورت یک تکه یاد بگیر.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:meine-telefonnummer-ist","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'pronunciation',3,'zwei','z را بشنو، به شروع ts توجه کن و بعد zwei را بگو.',1,CAST('{"mode":"sound_notice","target":"z_ts_zwei","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'speak',4,'Meine Telefonnummer ist null eins zwei drei.','آهسته و واضح تکرار کن.',1,CAST('{"mode":"repeat_visible","accepted":["Meine Telefonnummer ist null eins zwei drei.","Null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'speak',5,'شماره کوتاه صفر یک دو سه را بگو.','از حافظه تولید کن.',1,CAST('{"mode":"recall_hidden","cue_fa":"شماره کوتاه صفر یک دو سه را بگو.","accepted":["Null eins zwei drei.","Meine Telefonnummer ist null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'meaning_choice',6,'Meine ___ ist null eins zwei drei.','واژه درست را انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["Telefonnummer","Adresse","Sprache"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'reading',7,'Telefonnummer: 0 1 2 3','شماره را بخوان.',1,CAST('{"mode":"reading_input","text":"Telefonnummer: 0 1 2 3","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'reading_comprehension',8,'Welche Ziffer kommt nach eins?','از شماره پیدا کن.',1,CAST('{"mode":"reading_inference","options":["zwei","vier","null"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'word_order',9,'Meine Telefonnummer ist null eins','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["eins","Telefonnummer","Meine","null","ist"],"answer":["Meine","Telefonnummer","ist","null","eins"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'speak',10,'دوستی شماره‌ات را می‌خواهد.','پاسخ طبیعی بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"دوستی شماره‌ات را می‌خواهد.","accepted_intents":["Meine Telefonnummer ist null eins zwei drei.","Null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'speak',11,'از دوستت شماره‌اش را بپرس.','سوال را مستقل بساز.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"از دوستت شماره‌اش را بپرس.","accepted_intents":["Wie ist deine Telefonnummer?","Und wie ist deine Telefonnummer?"],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_1,'speak',12,'دو رقم اول شماره را دوباره بگو.','بدون جمله نمایان تولید کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"دو رقم اول شماره را دوباره بگو: صفر، یک.","accepted_intents":["Null eins.","Null, eins."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4));
INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_2,'listen',1,'null, eins, zwei, drei, vier, fünf','گوش کن و ترتیب را دنبال کن.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'new_word',2,'null bis fünf','رقم‌های صفر تا پنج را به صورت مجموعه کاربردی یاد بگیر.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:ziffern-0-5","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'pronunciation',3,'zwei','بشنو: z با ts شروع می‌شود؛ بعد خودت تولید کن.',1,CAST('{"mode":"sound_notice","target":"z_ts_zwei","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'speak',4,'null, eins, zwei, drei, vier, fünf','با ریتم آرام تکرار کن.',1,CAST('{"mode":"repeat_visible","accepted":["Null, eins, zwei, drei, vier, fünf.","Null eins zwei drei vier fünf."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'speak',5,'بگو دو، سه، چهار.','از حافظه بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو دو، سه، چهار.","accepted":["Zwei, drei, vier.","Zwei drei vier."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'meaning_choice',6,'eins, ___, drei','عدد جاافتاده را انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["zwei","fünf","null"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'reading',7,'0 – null | 2 – zwei | 5 – fünf','جدول کوتاه را بخوان.',1,CAST('{"mode":"reading_input","text":"0 – null | 2 – zwei | 5 – fünf","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'reading_comprehension',8,'Welche Zahl ist fünf?','از جدول انتخاب کن.',1,CAST('{"mode":"reading_inference","options":["5","2","0"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'word_order',9,'Wie ist deine Telefonnummer','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["Telefonnummer","deine","Wie","ist"],"answer":["Wie","ist","deine","Telefonnummer"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'speak',10,'رقم‌های صفر تا سه را به ترتیب بگو.','از حافظه تولید کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"رقم‌های صفر تا سه را به ترتیب بگو.","accepted_intents":["Null eins zwei drei.","Null, eins, zwei, drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'speak',11,'یک شماره کوتاه با چهار رقم صفر تا پنج بساز و بگو.','ترتیب تازه بساز.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"یک شماره کوتاه با چهار رقم صفر تا پنج بساز و بگو.","accepted_intents":["Null zwei vier fünf.","Eins drei vier fünf."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_2,'speak',12,'بعد از شنیدن «zwei» آن را با شروع درست تکرار کن.','روی تلفظ کاربردی تمرکز کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"بعد از شنیدن zwei آن را واضح تکرار کن.","accepted_intents":["Zwei.","Zwei!"],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4));
INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_3,'listen',1,'Woher kommst du? Wo wohnst du?','گوش کن و دو نوع اطلاعات را تشخیص بده.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'new_word',2,'Meine Telefonnummer ist ...','الگوی شماره را مرور کن.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:meine-telefonnummer-ist","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'pronunciation',3,'zwei','z را بشنو، تفاوتش با ز فارسی را توجه کن و تولید کن.',1,CAST('{"mode":"sound_notice","target":"z_ts_zwei","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'speak',4,'بگو اهل ایران هستی و در برلین زندگی می‌کنی.','review due Series 2 و 3 را ترکیب کن.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو اهل ایران هستی و در برلین زندگی می‌کنی.","accepted":["Ich komme aus dem Iran und wohne in Berlin.","Ich komme aus dem Iran. Ich wohne in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'speak',5,'بگو فارسی و کمی آلمانی صحبت می‌کنی.','review due Series 2 را از حافظه بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"بگو فارسی و کمی آلمانی صحبت می‌کنی.","accepted":["Ich spreche Persisch und ein bisschen Deutsch.","Persisch und ein bisschen Deutsch."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'meaning_choice',6,'Ich ___ in Berlin.','فعل درست را انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["wohne","spreche","heiße"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'reading',7,'Raha – Iran – Berlin – 0 1 2 3','کارت اطلاعات را بخوان.',1,CAST('{"mode":"reading_input","text":"Raha – Iran – Berlin – 0 1 2 3","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'reading_comprehension',8,'Welche Telefonnummer steht auf der Karte?','شماره را پیدا کن.',1,CAST('{"mode":"reading_inference","options":["0 1 2 3","2 3 4 5","0 0 1 1"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'word_order',9,'Ich komme aus dem Iran','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["Iran","dem","Ich","aus","komme"],"answer":["Ich","komme","aus","dem","Iran"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'speak',10,'فرد تازه مبدأ و محل زندگی‌ات را با هم می‌پرسد.','دو پاسخ را مستقل recombine کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"فرد تازه مبدأ و محل زندگی‌ات را با هم می‌پرسد.","accepted_intents":["Ich komme aus dem Iran und wohne in Berlin.","Aus dem Iran. Jetzt wohne ich in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'speak',11,'بعد زبانت و شماره کوتاهت را اضافه کن.','اطلاعات قدیم و جدید را ترکیب کن.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"بعد زبانت و شماره کوتاهت را اضافه کن.","accepted_intents":["Ich spreche Persisch. Meine Telefonnummer ist null eins zwei drei.","Persisch und ein bisschen Deutsch. Meine Telefonnummer ist null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_3,'speak',12,'یک معرفی کامل با نام، مبدأ، محل زندگی و شماره بساز.','بدون cue آلمانی مستقل بگو.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"یک معرفی کامل با نام، مبدأ، محل زندگی و شماره بساز.","accepted_intents":["Ich heiße Raha, komme aus dem Iran und wohne in Berlin. Meine Telefonnummer ist null eins zwei drei.","Ich bin Raha. Ich komme aus dem Iran. Ich wohne in Berlin. Meine Telefonnummer ist null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4));
INSERT INTO activities(lesson_id,activity_type,sort_order,prompt,instruction,difficulty,config,metadata) VALUES
(v_l_4,'listen',1,'Guten Tag. Wie heißen Sie?','گوش کن و موقعیت ثبت‌نام را بفهم.',1,CAST('{"mode":"audio_first","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'reading',2,'Kursanmeldung: Name – Wohnort – Telefonnummer','فرم کوتاه را بخوان.',1,CAST('{"mode":"reading_input","text":"Kursanmeldung: Name – Wohnort – Telefonnummer","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'reading_comprehension',3,'Welche Angabe braucht der Kurs?','از فرم نتیجه بگیر.',1,CAST('{"mode":"reading_inference","options":["Telefonnummer","Lieblingsfarbe","Frühstück"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'new_word',4,'Meine Telefonnummer ist ...','الگوی تماس را کوتاه مرور کن.',1,CAST('{"mode":"chunk_teach","unit_key":"de:a1:meine-telefonnummer-ist","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'pronunciation',5,'zwei','zwei را بشنو، ts آغازین را توجه کن و واضح بگو.',1,CAST('{"mode":"sound_notice","target":"z_ts_zwei","input":"none","scored":false}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'speak',6,'Meine Telefonnummer ist null eins zwei drei.','شماره را یک بار واضح بگو.',1,CAST('{"mode":"repeat_visible","accepted":["Meine Telefonnummer ist null eins zwei drei.","Null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'speak',7,'کارمند ثبت‌نام نامت را می‌پرسد.','در موقعیت تازه مستقل جواب بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"کارمند ثبت‌نام نامت را می‌پرسد.","accepted_intents":["Ich heiße Raha.","Mein Name ist Raha."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'speak',8,'او محل زندگی‌ات را می‌پرسد.','بدون راهنمای آلمانی پاسخ بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"کارمند محل زندگی‌ات را می‌پرسد.","accepted_intents":["Ich wohne in Berlin.","Jetzt wohne ich in Berlin."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'meaning_choice',9,'Meine ___ ist null eins zwei drei.','انتخاب کن.',1,CAST('{"mode":"sentence_blank","options":["Telefonnummer","Sprache","Herkunft"],"answer_index":0,"input":"tap_choice","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'word_order',10,'Meine Telefonnummer ist null eins','مرتب کن.',1,CAST('{"mode":"tap_tokens","tokens":["null","ist","Meine","eins","Telefonnummer"],"answer":["Meine","Telefonnummer","ist","null","eins"],"input":"tap_tokens","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'speak',11,'کارمند شماره تلفنت را می‌خواهد.','بدون نمونه پاسخ بده.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"کارمند شماره تلفنت را می‌خواهد.","accepted_intents":["Meine Telefonnummer ist null eins zwei drei.","Null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4)),(v_l_4,'speak',12,'ثبت‌نام را یک‌جا انجام بده: نام، مبدأ، محل زندگی و شماره را بگو.','novel-context mastery با recombination مستقل.',1,CAST('{"mode":"scenario_transfer","scenario_fa":"ثبت‌نام را یک‌جا انجام بده: نام، مبدأ، محل زندگی و شماره را بگو.","accepted_intents":["Ich heiße Raha, komme aus dem Iran und wohne in Berlin. Meine Telefonnummer ist null eins zwei drei.","Mein Name ist Raha. Ich komme aus dem Iran. Ich wohne in Berlin. Meine Telefonnummer ist null eins zwei drei."],"input":"speech","scored":true}' AS JSON),JSON_OBJECT('series',4));
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_1,id,'new',1,2,JSON_ARRAY(),JSON_OBJECT('series',4) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:telefonnummer-fragen','de:a1:meine-telefonnummer-ist','de:a1:ziffern-0-5','de:a1:possessive-meine-telefonnummer','de:a1:pron:z-ts-zwei','de:a1:can:phone-number');
INSERT IGNORE INTO sem_lesson_learning_units(lesson_id,learning_unit_id,learning_role,is_target,exposure_count,evidence_activity_ids,metadata) SELECT v_l_4,id,'mastery',1,1,JSON_ARRAY(),JSON_OBJECT('series',4) FROM sem_learning_units WHERE course_id=v_course AND unit_key IN('de:a1:telefonnummer-fragen','de:a1:meine-telefonnummer-ist','de:a1:ziffern-0-5','de:a1:possessive-meine-telefonnummer','de:a1:pron:z-ts-zwei','de:a1:can:phone-number');
INSERT IGNORE INTO sem_turn_learning_units(turn_id,learning_unit_id,evidence_type,metadata) SELECT t.id,lu.id,'mastery',JSON_OBJECT('series',4) FROM turns t JOIN sem_learning_units lu ON lu.course_id=v_course AND lu.unit_key='de:a1:can:phone-number' WHERE t.lesson_id=v_l_4 AND t.sort_order=6 LIMIT 1;
INSERT IGNORE INTO sem_review_obligations(course_id,learning_unit_id,origin_chapter_id,due_series,spacing_offset,status,metadata) SELECT v_course,lu.id,v_chapter,4+o.off,o.off,'due',JSON_OBJECT('originSeries',4) FROM sem_learning_units lu JOIN(SELECT 1 off UNION ALL SELECT 2 UNION ALL SELECT 4 UNION ALL SELECT 8 UNION ALL SELECT 16)o WHERE lu.course_id=v_course AND lu.unit_key IN('de:a1:telefonnummer-fragen','de:a1:meine-telefonnummer-ist','de:a1:ziffern-0-5','de:a1:possessive-meine-telefonnummer','de:a1:pron:z-ts-zwei','de:a1:can:phone-number');
