-- SERIES 4
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS nova_de_v32_s0004;
DELIMITER $$
CREATE PROCEDURE nova_de_v32_s0004()
BEGIN
DECLARE v_count INT DEFAULT 0; DECLARE v_course BIGINT UNSIGNED; DECLARE v_level BIGINT UNSIGNED; DECLARE v_module BIGINT UNSIGNED; DECLARE v_chapter BIGINT UNSIGNED; DECLARE v_c_raha BIGINT UNSIGNED; DECLARE v_c_lena BIGINT UNSIGNED; DECLARE v_c_jonas BIGINT UNSIGNED; DECLARE v_l_1 BIGINT UNSIGNED; DECLARE v_l_2 BIGINT UNSIGNED; DECLARE v_l_3 BIGINT UNSIGNED; DECLARE v_l_4 BIGINT UNSIGNED;
DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
START TRANSACTION;
SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='de' AND base_language='fa'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa course identity missing or not unique'; END IF;
SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1'; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa A1 missing or not unique'; END IF;
SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1; IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa module 1 missing or not unique'; END IF;
SELECT id INTO v_c_raha FROM characters WHERE course_id=v_course AND name='Raha' AND gender='female' LIMIT 1; SELECT id INTO v_c_lena FROM characters WHERE course_id=v_course AND name='Lena' AND gender='female' LIMIT 1;
IF v_c_raha IS NULL OR v_c_lena IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='de-fa Series 4 requires Raha and Lena'; END IF;
SELECT COUNT(*) INTO v_count FROM characters WHERE course_id=v_course AND name='Jonas'; IF v_count=0 THEN INSERT INTO characters(course_id,name,gender,profile,metadata) VALUES(v_course,'Jonas','male',JSON_OBJECT('role','Mitarbeiter im Sprachkursbüro'),JSON_OBJECT('nativeV3',TRUE,'context','language course registration contact in Berlin')); END IF;
SELECT id INTO v_c_jonas FROM characters WHERE course_id=v_course AND name='Jonas' AND gender='male' LIMIT 1;
SELECT COUNT(*),MIN(id) INTO v_count,v_chapter FROM chapters WHERE module_id=v_module AND sort_order=4;
IF v_count=0 THEN
SET v_chapter=LAST_INSERT_ID();
ON DUPLICATE KEY UPDATE display_form=VALUES(display_form),translation=VALUES(translation),description_fa=VALUES(description_fa);
ON DUPLICATE KEY UPDATE status='in_progress';
SELECT id INTO v_l_1 FROM lessons WHERE chapter_id=v_chapter AND sort_order=1 LIMIT 1; SELECT id INTO v_l_2 FROM lessons WHERE chapter_id=v_chapter AND sort_order=2 LIMIT 1; SELECT id INTO v_l_3 FROM lessons WHERE chapter_id=v_chapter AND sort_order=3 LIMIT 1; SELECT id INTO v_l_4 FROM lessons WHERE chapter_id=v_chapter AND sort_order=4 LIMIT 1;
UPDATE sem_review_obligations ro
JOIN sem_learning_units lu ON lu.id=ro.learning_unit_id
JOIN activities a ON a.lesson_id=v_l_3 AND a.sort_order=
CASE
WHEN lu.unit_key IN('de:a1:ich-komme-aus','de:a1:woher-kommst-du') THEN 4
WHEN lu.unit_key IN('de:a1:ich-spreche','de:a1:ein-bisschen-deutsch','de:a1:verb-position-1','de:a1:pron:ich-laut','de:a1:can:origin-language') THEN 5
WHEN lu.unit_key IN('de:a1:ich-wohne-in','de:a1:wo-wohnst-du','de:a1:wo-wohnen-sie','de:a1:wohnen-present','de:a1:pron:long-o-wohnen','de:a1:can:residence') THEN 10
ELSE 12 END
SET ro.status='fulfilled',ro.fulfilled_chapter_id=v_chapter,ro.evidence_activity_id=a.id
WHERE ro.course_id=v_course AND ro.due_series=4 AND ro.status='due';
END IF;
COMMIT;
END$$
DELIMITER ;
CALL nova_de_v32_s0004();
DROP PROCEDURE IF EXISTS nova_de_v32_s0004;
